/*
 * sentences-model.js — example sentences / vocab in context (v16 lane items R11 + R11b). Pure: no DOM, no storage.
 * Exposes window.SentencesModel; also CommonJS for tests. Data: context-sentences-n5.js … -n1.js, one per JLPT
 * level (each registers self.CONTEXT_SENTENCES[level]), generated by kanji-five/r11/build_sentences.py from
 * Tatoeba (CC BY 2.0 FR) + JMdict (EDRDG, CC BY-SA 4.0).
 *
 * R11b lazy loading: only the N5 file is precached and loaded at startup; it carries `index` (kanji → level).
 * createStore(loadLevel) keeps the loaded levels; other levels are loaded on first use (loadLevel returns a Promise
 * of the level data). If a level cannot be loaded (offline, never cached), candidates() falls back to sentences
 * from levels already loaded whose target word contains the kanji, else [] — prompts degrade to "no sentence",
 * never throw. A failed level is retried on the next ensure().
 *
 * R11b reading in context: every candidate has `reading` (the word's reading in THAT sentence) and `rsrc`:
 * 1 = Tatoeba B-line (Tanaka index) reading, 2 = JMdict's only reading of the exact form, 0 = unknown → any listed
 * reading is accepted and the prompt is flagged readingCertain:false. Grading: the sentence reading → good;
 * R5 near-miss of it → hard; another valid reading of the word (e.g. じん for 人 read ひと here) → hard,
 * verdict 'other-reading'; anything else → again.
 *
 * Selection (runtime): each kanji has a small candidate pool. choose() ranks candidates by the number of
 * UNLEARNED kanji in the sentence (isKnown: rank > 0, or a component of the target), then length, then id.
 *
 * Reading-in-context prompt: the sentence is shown with the target WORD marked; the learner types its reading.
 * Graded with R5 PartialCredit.grade (exact → good, near → hard, wrong → again).
 *
 * Scheduler choice (documented): a SEPARATE context card, key 'ctx:<kanji>', graded through the normal
 * V15 gradeKey path (same FSRS, retention, smoothing, load budget). Not the kanji's own card, because the kanji's
 * card is driven by the writing/reading ladder (rank events, recFinish) and a context miss — often caused by
 * a different word — would otherwise lapse the kanji itself. ctx cards are excluded from leech tracking.
 *
 * ---- UI hooks for Botfour ----
 *   p = V15.contextPrompt(storage, kanji, {kanjiMap}) → null or {key, kanji, before, word, after, en, readings,
 *       attribution:{text, links:[{label, url}], license, licenseUrl}}
 *     Show: before + <mark>word</mark> + after; input for the reading; optional English (after answering).
 *     p.readingCertain false → any listed reading was accepted; show e.g. "(reading not checked for this sentence)".
 *     p.fallback true → offline: a sentence from an already-loaded level (same display).
 *   Lazy levels (R11b): V15.sentencesReady(kanji) → bool; V15.loadSentences(kanji) → Promise<bool>;
 *     V15.contextPromptAsync(storage, kanji, opts) → Promise<prompt|null> (loads the level first; never rejects).
 *     The sync calls (sentencesFor, contextPrompt) return what is loaded now (or the fallback) and start the load.
 *   r = V15.gradeContext(storage, p, answer, {now}) → {verdict, grade, expected, segments, card}
 *     Same result shape as R5 partial credit, so the R5 feedback styling can be reused.
 *   V15.contextDue(storage, now) → ['ctx:人', …] due context cards (queue them after normal reviews).
 *   ATTRIBUTION IS REQUIRED by CC BY 2.0 FR / CC BY-SA 4.0: always show p.attribution.text near the sentence
 *   (small text is fine) with p.attribution.links (Tatoeba sentence page(s), license). An "About / credits" page
 *   should also show SentencesModel.credits(data).
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.SentencesModel = api;
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const CTX_PREFIX = 'ctx:';
  const isKanji = (ch) => /[\u3400-\u4dbf\u4e00-\u9fff々]/.test(ch);

  /** Candidates of one kanji as objects (empty when the kanji has none). */
  function pool(data, kanji) {
    if (!data || !data.kanji || !Array.isArray(data.kanji[kanji])) return [];
    const F = data.meta.fields;
    return data.kanji[kanji].map((row) => {
      const c = {}; F.forEach((f, i) => { c[f] = row[i]; });
      const w = (data.words || {})[c.word] || [[], null, null];
      return Object.assign(c, {
        kanji, jaAuthor: data.authors[c.jaAuthor] || null, enAuthor: data.authors[c.enAuthor] || null,
        readings: w[0].slice(), wordId: w[1], wordSrc: w[2], reading: c.reading || '', rsrc: c.rsrc || 0,
      });
    });
  }

  /** Kanji in the sentence (other than the target) the learner does not know yet, in order, de-duplicated. */
  function unlearned(c, isKnown) {
    const out = [];
    for (const ch of c.ja) if (isKanji(ch) && ch !== c.kanji && !isKnown(ch) && !out.includes(ch)) out.push(ch);
    return out;
  }

  /** Best 1–2 candidates: fewest unlearned kanji, then shorter, then lower Tatoeba id (stable). */
  function choose(data, kanji, isKnown = () => false, { limit = 2 } = {}) {
    return pool(data, kanji).map((c) => Object.assign(c, { unlearned: unlearned(c, isKnown) }))
      .sort((a, b) => a.unlearned.length - b.unlearned.length || a.ja.length - b.ja.length || a.jaId - b.jaId)
      .slice(0, limit);
  }

  /** License attribution for one candidate (MUST be shown with the sentence). */
  function attribution(data, c) {
    const T = data.meta.sources[0]; const J = data.meta.sources[1];
    const url = (id) => T.sentenceUrl.replace('{id}', id);
    const by = (a) => (a ? ' by ' + a : '');
    const text = 'Tatoeba #' + c.jaId + by(c.jaAuthor) + ' / #' + c.enId + by(c.enAuthor) + ' (' + T.license + ')'
      + (c.wordSrc === 'jmdict' ? '; reading: JMdict, EDRDG (' + J.license + ')' : '');
    const links = [{ label: 'Tatoeba #' + c.jaId, url: url(c.jaId) }, { label: 'Tatoeba #' + c.enId, url: url(c.enId) },
      { label: T.license, url: T.licenseUrl }];
    if (c.wordSrc === 'jmdict') links.push({ label: 'JMdict ' + J.license, url: J.licenseUrl });
    return { text, links, license: T.license, licenseUrl: T.licenseUrl };
  }

  /** Full credits text for an About page. */
  function credits(data) {
    return data.meta.sources.map((s) => s.attribution + ' ' + s.url + ' — ' + s.license + ' ' + s.licenseUrl).join('\n');
  }

  /** Reading-in-context prompt for the best candidate, or null when there is none. */
  function prompt(data, kanji, isKnown) {
    const c = choose(data, kanji, isKnown, { limit: 1 })[0];
    return promptFor(data, kanji, c);
  }

  /** Prompt object for one chosen candidate (also used by the store). */
  function promptFor(data, kanji, c) {
    if (!c || c.ja.slice(c.at, c.at + c.word.length) !== c.word || !(c.reading || c.readings.length)) return null;
    const certain = c.rsrc > 0 && !!c.reading;
    return { key: CTX_PREFIX + kanji, kanji, jaId: c.jaId, sentence: c.ja, before: c.ja.slice(0, c.at), word: c.word,
      after: c.ja.slice(c.at + c.word.length), en: c.en,
      accepted: certain ? [c.reading] : c.readings.slice(),            // what counts as fully right
      readings: c.readings, readingCertain: certain, readingSource: c.rsrc,
      unlearned: c.unlearned, attribution: attribution(data, c) };
  }

  /**
   * Grade a typed reading with R5 PartialCredit (pc passed in; no load-order dependency).
   * Returns PartialCredit's result; verdict 'other-reading' (grade hard) for a valid reading the word does not
   * have in this sentence. readingCertain is copied so the UI can say "accepted any reading".
   */
  function grade(p, answer, pc) {
    if (!p) return pc.grade(answer, []);
    const accepted = p.accepted || p.readings;
    const r = pc.grade(answer, accepted);
    if (r.verdict === 'wrong') {
      const others = (p.readings || []).filter((x) => !accepted.includes(x));
      if (others.length && pc.grade(answer, others).verdict === 'exact') {
        Object.assign(r, { verdict: 'other-reading', grade: 'hard', reasons: ['other-reading'] });
      }
    }
    return Object.assign(r, { readingCertain: p.readingCertain !== false });
  }

  /**
   * Level store (R11b). loadLevel(level) → Promise<level data>. add(data) registers a loaded file (N5 at startup).
   *   levelOf(k)   level file holding k (from the N5 index), or null
   *   ready(k)     true when k's level is loaded (or k has no sentences at all)
   *   ensure(k)    Promise<boolean>: loads k's level once; false on failure (retried next call)
   *   candidates(k, isKnown, limit) → chosen candidates from k's level, else the offline fallback, else []
   *   prompt(k, isKnown) → prompt or null
   */
  function createStore(loadLevel) {
    const levels = {}; const pending = {}; let index = {};
    const store = {
      add(d) { if (d && d.level) { levels[d.level] = d; if (d.index) index = d.index; } return store; },
      loaded: () => Object.keys(levels),
      levelOf: (k) => index[k] || null,
      ready: (k) => !index[k] || !!levels[index[k]],
      ensure(k) {
        const lv = index[k];
        if (!lv || levels[lv]) return Promise.resolve(!!lv);
        if (!pending[lv]) {
          pending[lv] = Promise.resolve().then(() => loadLevel(lv))
            .then((d) => { store.add(d); return !!levels[lv]; }, () => false)
            .then((ok) => { delete pending[lv]; return ok; });
        }
        return pending[lv];
      },
      candidates(k, isKnown = () => false, limit = 2) {
        const lv = index[k];
        if (lv && levels[lv]) return choose(levels[lv], k, isKnown, { limit }).map((c) => Object.assign(c, { data: levels[lv] }));
        // offline fallback: another kanji's sentences (already loaded) whose word contains k
        const out = [];
        for (const d of Object.values(levels)) {
          for (const owner of Object.keys(d.kanji)) {
            for (const c of pool(d, owner)) {
              if (c.word.includes(k) && !out.some((o) => o.jaId === c.jaId)) {
                c.kanji = k; c.fallback = true; c.data = d; c.unlearned = unlearned(c, isKnown); out.push(c);
              }
            }
          }
        }
        return out.sort((a, b) => a.unlearned.length - b.unlearned.length || a.ja.length - b.ja.length || a.jaId - b.jaId).slice(0, limit);
      },
      prompt(k, isKnown) {
        const c = store.candidates(k, isKnown, 1)[0];
        const p = c ? promptFor(c.data, k, c) : null;
        if (p && c.fallback) p.fallback = true;
        return p;
      },
    };
    return store;
  }

  return { CTX_PREFIX, pool, unlearned, choose, attribution, credits, prompt, promptFor, grade, createStore };
});
